using System; using System.IO;
public class RangeReport {
 public long Zero,Nonzero,EligibleNonzero,EligibleGroups,Groups;
 public long[] Exponents=new long[256];
 public static RangeReport Read(string path) {
  var r=new RangeReport();var bytes=File.ReadAllBytes(path);bool valid=true;
  for(int i=0;i<bytes.Length;i+=2) {
   int w=bytes[i]|(bytes[i+1]<<8),e=(w>>7)&255;
   if((w&32767)==0) ++r.Zero;
   else {++r.Nonzero;++r.Exponents[e];bool good=e>=64&&e<=190;if(good)++r.EligibleNonzero;valid&=good;}
   if((i%32)==30) {++r.Groups;if(valid)++r.EligibleGroups;valid=true;}
  }
  return r;
 }
}
